function sumOfPower(nums, k) {
  const MOD = 1000000007;
  const dp = new Array(k + 1).fill(0);
  dp[0] = 1;

  for (const num of nums) {
    for (let sum = k; sum >= 0; sum--) {
      const skip = (dp[sum] * 2) % MOD;
      const take = sum >= num ? dp[sum - num] : 0;
      dp[sum] = (skip + take) % MOD;
    }
  }
  return dp[k];
}

brute:
function sumOfPower(nums, k) {
  // Count the subsets T that add up to k exactly, by size, with BigInt (no modulus until the end).
  // A subset of size j lies inside 2^(n - j) subsequences, and it adds 1 to the power of each one.
  const n = nums.length;
  const ways = Array.from({ length: n + 1 }, () => new Array(k + 1).fill(0n));
  ways[0][0] = 1n;
  for (const value of nums) {
    for (let size = n; size >= 1; size--) {
      for (let s = k; s >= value; s--) ways[size][s] += ways[size - 1][s - value];
    }
  }
  let total = 0n;
  for (let size = 1; size <= n; size++) total += ways[size][k] * 2n ** BigInt(n - size);
  return Number(total % 1000000007n);
}

