function generate(rand, size) {
  const pick = limit => Math.floor(rand() * limit);
  if (size === 'small') {
    const n = 1 + pick(9);
    const k = 1 + pick(12);
    const top = rand() < 0.15 ? 10000 : 1 + pick(8);
    return [Array.from({ length: n }, () => 1 + pick(top)), k];
  }
  const n = 80 + pick(21);
  const k = 50 + pick(51);
  // Mostly small values so that many subsets reach k, with a few values too big to ever help.
  const small = 1 + pick(30);
  const nums = Array.from({ length: n }, () => (rand() < 0.1 ? 101 + pick(9900) : 1 + pick(small)));
  return [nums, k];
}
